local function applySkyDataToInstance(sky, d)
    if not sky or not d then return end
    sky.CelestialBodiesShown=d.CelestialBodiesShown~=false
    sky.StarCount=d.StarCount or 3000
    sky.SunAngularSize=d.SunAngularSize or 21
    sky.MoonAngularSize=d.MoonAngularSize or 11
    sky.SunTextureId=d.SunTextureId or 'rbxasset://sky/sun.jpg'
    sky.MoonTextureId=d.MoonTextureId or 'rbxasset://sky/moon.jpg' 
    sky.SkyboxBk = d.Bk or ""
    sky.SkyboxDn = d.Dn or ""
    sky.SkyboxFt = d.Ft or ""
    sky.SkyboxLf = d.Lf or ""
    sky.SkyboxRt = d.Rt or ""
    sky.SkyboxUp = d.Up or ""
    if d.SunTextureId ~= nil then pcall(function() sky.SunTextureId = d.SunTextureId end) end
    if d.MoonTextureId ~= nil then pcall(function() sky.MoonTextureId = d.MoonTextureId end) end
    if d.StarCount ~= nil then pcall(function() sky.StarCount = d.StarCount end) end
    if d.CelestialBodiesShown ~= nil then pcall(function() sky.CelestialBodiesShown = d.CelestialBodiesShown end) end
end

